  function togglePricing() {
    const checkbox = document.getElementById('toggle-checkbox');
    const pill = document.getElementById('toggle-pill');
    const labelMo = document.getElementById('label-mo');
    const labelYr = document.getElementById('label-yr');
    const prices = document.querySelectorAll('.price-val');

    if (!checkbox || !pill || !labelMo || !labelYr || !prices.length) return;

    const isYearly = checkbox.checked;

    if (isYearly) {
      pill.style.transform = 'translateX(100%)';

      labelMo.classList.remove('text-slate-800');
      labelMo.classList.add('text-slate-400');

      labelYr.classList.remove('text-slate-400');
      labelYr.classList.add('text-slate-800');
    } else {
      pill.style.transform = 'translateX(0)';

      labelMo.classList.remove('text-slate-400');
      labelMo.classList.add('text-slate-800');

      labelYr.classList.remove('text-slate-800');
      labelYr.classList.add('text-slate-400');
    }

    prices.forEach(el => {
      const targetPrice = isYearly ? el.dataset.yearly : el.dataset.monthly;
      const end = parseInt(targetPrice, 10);
      let start = parseInt(el.textContent.trim(), 10);

      if (!Number.isFinite(start) || !Number.isFinite(end) || start === end) {
        el.textContent = targetPrice;
        return;
      }

      const duration = 260;
      const distance = Math.abs(end - start);
      const stepTime = Math.max(6, Math.floor(duration / distance));

      const timer = setInterval(() => {
        start = start < end ? start + 1 : start - 1;
        el.textContent = start;

        if (start === end) {
          clearInterval(timer);
        }
      }, stepTime);
    });
  }

